  ('laikipia-kenya', '05A', 'Laikipia Plateau', 'Kenya', 'Kenya''s conservancy country', 'live', 'verified', 'lion', 'Kenya — Laikipia Plateau', '{"safari","ultra","adventure","romance","deepdive"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'anchor', '{"key_facts":["Kenya''s private-conservancy heartland (Ol Pejeta, Lewa, Borana, Loisaba, Solio) - low-density, exclusive; the LAST TWO northern white rhinos on Earth (Najin + Fatu, Ol Pejeta, on-site IVF programme)","Ol Pejeta (90,000 acres) = largest black-rhino population in East Africa + Sweetwaters Chimpanzee Sanctuary (only chimps in Kenya); Lewa (UNESCO 2013) = ~12% of Kenya''s black rhino + largest Grevy''s zebra population","Do-more safari on private land: horseback safaris, walking safaris (armed guide), night drives, lion tracking, mountain biking, camel treks, star beds - all banned in the national parks","best Jul-Oct + Dec-Mar but rewarding year-round - the anchor when migration parks peak-price","Sold via Kenya safari DMCs at a FAVOURABLE 15-22% - IATAN/host-gated, CLIA has NO Africa representation; conservancy/conservation fees non-commissionable pass-through","KES (~129/USD) + M-Pesa but safari quoted USD; eTA required; malaria lower at ~1,800m but present (prophylaxis advised); YF only if arriving from a risk country; AMREF for the on-foot/horse activities"],"safety":{"emergency":"999 / 112 (limited in remote areas); Kenya Red Cross ambulance 1199; AMREF Flying Doctors for bush evac","hospital":"Remote plateau - AMREF Flying Doctors (~$40 pp/30d, air evac) + travel-medical insurance; nearest referral Nanyuki/Nairobi","malaria":"lower at ~1,800m but present - prophylaxis advised (chloroquine-resistant); DEET at dusk","yellow_fever":"compulsory only if arriving from a risk country; CDC recommends for most","activity_note":"Signature on-foot/on-horse/night safaris among dangerous game - armed conservancy guides only, higher-risk than a vehicle, follow instruction. Remote - carry AMREF evac + insurance","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/kenya","read":"2026-08-20T14:53:50Z","page_updated":"2026-06-24T12:48:44+01:00","source_country":"kenya","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"Mandera, Wajir and Garissa counties","lvl":4,"note":"The Somalia border counties."},{"name":"Lamu County","lvl":4},{"name":"Tana River","lvl":4},{"name":"Kilifi north of Malindi","lvl":4},{"name":"The northern border areas","lvl":4},{"name":"Eastleigh, Nairobi","lvl":3},{"name":"Kibera, Nairobi","lvl":3}]},"timing":{"peak":"Jul-Oct + Dec-Mar (dry) - best game + activities; conservancy camps busiest but low-density caps keep it quiet","shoulder":"Jun + Nov (good, softer rates)","green":"Apr-May (long rains - lush, quiet, cheapest; plateau still delivers)","booking_lead":"conservancy lodges 4-9 mo (Jul-Oct + Dec-Mar; camps small + capped); shoulder 2-4 mo; green 1-2 mo","off_season_specials":"Apr-May green-season value; the year-round anchor when migration parks peak-price; combine Samburu (Special Five) or the Mara","event_peaks":"Jul-Oct + Christmas/NY + Easter; Lewa Safari Marathon (~Jun, verify) spikes Lewa","fire_date":"conservancy weeks 6-9 mo out; market year-round + green value vs the migration-park price crush; bundle Laikipia (rhino) + Amboseli/Mara to complete the Big Five"},"jewels":[{"name":"The last two northern white rhinos (Ol Pejeta)","si_tag":"safari","status":"live","tier":"premier","price_band":"~$600-2,000/pp/day","timing":"Jul-Oct + Dec-Mar","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"stand beside Najin and Fatu — the last two northern white rhinos on Earth","si":"safari","blurb":"stand beside Najin and Fatu — the last two northern white rhinos on Earth","when":"Jul-Oct + Dec-Mar","commission":"conservancy DMC 15-22%",